#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, F;
    cin >> N >> F;

    vector<string> grid(N);
    for (auto& row : grid) cin >> row;

    if (grid[0][0] <= char('0' + F)) {
        queue<pair<int, int>> q;
        q.push({0, 0});
        grid[0][0] = '*';

        const int dr[] = {-1, 1, 0, 0};
        const int dc[] = {0, 0, -1, 1};

        while (!q.empty()) {
            auto [r, c] = q.front();
            q.pop();

            for (int d = 0; d < 4; ++d) {
                int nr = r + dr[d];
                int nc = c + dc[d];

                if (nr >= 0 && nr < N && nc >= 0 && nc < N &&
                    grid[nr][nc] != '*' && grid[nr][nc] <= char('0' + F)) {
                    grid[nr][nc] = '*';
                    q.push({nr, nc});
                }
            }
        }
    }

    for (const auto& row : grid) cout << row << '\n';
    return 0;
}
